INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-numbers-a1-01-01', 'lesson-numbers-a1-01', 1, 'sentence', 'I am twenty-five years old.', 'Tenho vinte e cinco anos.', '/aɪ æm ˌtwɛntiˈfaɪv jɪrz oʊld/', 'Idade usa "to be". "Years old" é opcional: "I am twenty-five".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"twenty-five","pos":"numeral","ipa":"/ˌtwɛntiˈfaɪv/","gloss":"vinte e cinco"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-01-02', 'lesson-numbers-a1-01', 2, 'sentence', 'My son is three.', 'Meu filho tem três anos.', '/maɪ sʌn ɪz θriː/', 'Forma curta, sem "years old".', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"son","pos":"noun","ipa":"/sʌn/","gloss":"filho"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-01-03', 'lesson-numbers-a1-01', 3, 'sentence', 'How old is your mother?', 'Quantos anos tem sua mãe?', '/haʊ oʊld ɪz jʊr ˈmʌðər/', '"How old" pergunta a idade.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"mother","pos":"noun","ipa":"/ˈmʌðər/","gloss":"mãe"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-01-04', 'lesson-numbers-a1-01', 4, 'sentence', 'She is in her thirties.', 'Ela tem trinta e poucos anos.', '/ʃiː ɪz ɪn hɜːr ˈθɜːrtiz/', '"In her thirties" = entre 30 e 39.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"thirties","pos":"noun","ipa":"/ˈθɜːrtiz/","gloss":"os trinta (idade)"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-01-05', 'lesson-numbers-a1-01', 5, 'sentence', 'There are fifteen people in the room.', 'Tem quinze pessoas na sala.', '/ðɛr ɑːr ˌfɪfˈtiːn ˈpiːpəl ɪn ðə ruːm/', 'Força no fim: fif-TEEN.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"fifteen","pos":"numeral","ipa":"/ˌfɪfˈtiːn/","gloss":"quinze"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-01-06', 'lesson-numbers-a1-01', 6, 'sentence', 'We need fifty chairs.', 'Precisamos de cinquenta cadeiras.', '/wiː niːd ˈfɪfti tʃɛrz/', 'Força no começo: FIF-ty.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"fifty","pos":"numeral","ipa":"/ˈfɪfti/","gloss":"cinquenta"},{"surface":"chairs","pos":"noun","ipa":"/tʃɛrz/","gloss":"cadeiras"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-01-07', 'lesson-numbers-a1-01', 7, 'sentence', 'I have two brothers and one sister.', 'Tenho dois irmãos e uma irmã.', '/aɪ hæv tuː ˈbrʌðərz ænd wʌn ˈsɪstər/', '"Brothers" é só irmãos homens; irmãos em geral = "siblings".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"brothers","pos":"noun","ipa":"/ˈbrʌðərz/","gloss":"irmãos"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"sister","pos":"noun","ipa":"/ˈsɪstər/","gloss":"irmã"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-01-08', 'lesson-numbers-a1-01', 8, 'sentence', 'About a hundred people came.', 'Umas cem pessoas vieram.', '/əˈbaʊt ə ˈhʌndrəd ˈpiːpəl keɪm/', '"About" = aproximadamente.', '[]'::jsonb, '[{"surface":"About","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"hundred","pos":"numeral","ipa":"/ˈhʌndrəd/","gloss":"cem, centena"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"came","pos":"verb","ipa":"/keɪm/","gloss":"veio"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-01-09', 'lesson-numbers-a1-01', 9, 'sentence', 'The city has two million people.', 'A cidade tem dois milhões de pessoas.', '/ðə ˈsɪti hæz tuː ˈmɪljən ˈpiːpəl/', '"Million" não vai para o plural com número.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"million","pos":"numeral","ipa":"/ˈmɪljən/","gloss":"milhão"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-01-10', 'lesson-numbers-a1-01', 10, 'sentence', 'I''m the second of three kids.', 'Sou o segundo de três filhos.', '/aɪm ðə ˈsɛkənd ʌv θriː kɪdz/', 'Ordinal: second.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"second","pos":"adjective","ipa":"/ˈsɛkənd/","gloss":"segundo"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"},{"surface":"kids","pos":"noun","ipa":"/kɪdz/","gloss":"crianças, filhos"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-numbers-a1-02-01', 'lesson-numbers-a1-02', 1, 'sentence', 'How much is this?', 'Quanto custa isto?', '/haʊ mʌtʃ ɪz ðɪs/', 'Pergunta de preço mais comum.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-02-02', 'lesson-numbers-a1-02', 2, 'sentence', 'It''s ten dollars.', 'Custa dez dólares.', '/ɪts tɛn ˈdɑːlərz/', '"It''s" + preço.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"},{"surface":"dollars","pos":"noun","ipa":"/ˈdɑːlərz/","gloss":"dólares"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-02-03', 'lesson-numbers-a1-02', 3, 'sentence', 'It''s nine ninety-nine.', 'Custa nove e noventa e nove.', '/ɪts naɪn ˌnaɪntiˈnaɪn/', '$9.99 é lido em dois blocos: "nine ninety-nine".', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"nine","pos":"numeral","ipa":"/naɪn/","gloss":"nove"},{"surface":"ninety-nine","pos":"numeral","ipa":"/ˌnaɪntiˈnaɪn/","gloss":"noventa e nove"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-02-04', 'lesson-numbers-a1-02', 4, 'sentence', 'The total is forty-five fifty.', 'O total é quarenta e cinco e cinquenta.', '/ðə ˈtoʊtəl ɪz ˌfɔːrtiˈfaɪv ˈfɪfti/', '$45.50 = "forty-five fifty".', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"total","pos":"noun","ipa":"/ˈtoʊtəl/","gloss":"total"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"forty-five","pos":"numeral","ipa":"/ˌfɔːrtiˈfaɪv/","gloss":"quarenta e cinco"},{"surface":"fifty","pos":"numeral","ipa":"/ˈfɪfti/","gloss":"cinquenta"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-02-05', 'lesson-numbers-a1-02', 5, 'sentence', 'That will be twelve dollars, please.', 'São doze dólares, por favor.', '/ðæt wɪl biː twɛlv ˈdɑːlərz pliːz/', 'Fala do caixa: "That will be…".', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"twelve","pos":"numeral","ipa":"/twɛlv/","gloss":"doze"},{"surface":"dollars","pos":"noun","ipa":"/ˈdɑːlərz/","gloss":"dólares"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-02-06', 'lesson-numbers-a1-02', 6, 'sentence', 'Do you have change for twenty?', 'Tem troco para vinte?', '/duː juː hæv tʃeɪndʒ fɔːr ˈtwɛnti/', '"Change for" + nota.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"twenty","pos":"numeral","ipa":"/ˈtwɛnti/","gloss":"vinte"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-02-07', 'lesson-numbers-a1-02', 7, 'sentence', 'It costs a hundred and twenty dollars.', 'Custa cento e vinte dólares.', '/ɪt kɔːsts ə ˈhʌndrəd ænd ˈtwɛnti ˈdɑːlərz/', 'No inglês britânico entra "and": "a hundred and twenty".', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"costs","pos":"verb","ipa":"/kɔːsts/","gloss":"custa"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"hundred","pos":"numeral","ipa":"/ˈhʌndrəd/","gloss":"cem, centena"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"twenty","pos":"numeral","ipa":"/ˈtwɛnti/","gloss":"vinte"},{"surface":"dollars","pos":"noun","ipa":"/ˈdɑːlərz/","gloss":"dólares"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-02-08', 'lesson-numbers-a1-02', 8, 'sentence', 'Can you give me a discount?', 'Pode me dar um desconto?', '/kæn juː ɡɪv miː ə ˈdɪskaʊnt/', 'Pedido direto e educado.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"give","pos":"verb","ipa":"/ɡɪv/","gloss":"dar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"discount","pos":"noun","ipa":"/ˈdɪskaʊnt/","gloss":"desconto"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-02-09', 'lesson-numbers-a1-02', 9, 'sentence', 'It was half price.', 'Estava pela metade do preço.', '/ɪt wɑːz hæf praɪs/', '"Half price" = 50% de desconto.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"half","pos":"noun","ipa":"/hæf/","gloss":"metade, meio"},{"surface":"price","pos":"noun","ipa":"/praɪs/","gloss":"preço"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-02-10', 'lesson-numbers-a1-02', 10, 'sentence', 'That''s too expensive for me.', 'Está caro demais para mim.', '/ðæts tuː ɪkˈspɛnsɪv fɔːr miː/', '"Too" + adjetivo = demais.', '[]'::jsonb, '[{"surface":"That''s","pos":"pronoun","ipa":"/ðæts/","gloss":"isso é"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-numbers-a1-03-01', 'lesson-numbers-a1-03', 1, 'sentence', 'What''s your phone number?', 'Qual é o seu telefone?', '/wʌts jʊr foʊn ˈnʌmbər/', 'Pergunta padrão.', '[]'::jsonb, '[{"surface":"What''s","pos":"pronoun","ipa":"/wʌts/","gloss":"qual é"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"number","pos":"noun","ipa":"/ˈnʌmbər/","gloss":"número"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-03-02', 'lesson-numbers-a1-03', 2, 'sentence', 'My number is five five five, two oh four one.', 'Meu número é cinco cinco cinco, dois zero quatro um.', '/maɪ ˈnʌmbər ɪz faɪv faɪv faɪv tuː oʊ fɔːr wʌn/', 'O zero em telefone costuma ser "oh".', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"number","pos":"noun","ipa":"/ˈnʌmbər/","gloss":"número"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"oh","pos":"interjection","ipa":"/oʊ/","gloss":"ah, oh"},{"surface":"four","pos":"numeral","ipa":"/fɔːr/","gloss":"quatro"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-03-03', 'lesson-numbers-a1-03', 3, 'sentence', 'Can you repeat that, please?', 'Pode repetir, por favor?', '/kæn juː rɪˈpiːt ðæt pliːz/', 'Essencial ao anotar números.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"repeat","pos":"verb","ipa":"/rɪˈpiːt/","gloss":"repetir"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-03-04', 'lesson-numbers-a1-03', 4, 'sentence', 'Can you spell your name?', 'Pode soletrar seu nome?', '/kæn juː spɛl jʊr neɪm/', '"Spell" = soletrar.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"spell","pos":"verb","ipa":"/spɛl/","gloss":"soletrar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-03-05', 'lesson-numbers-a1-03', 5, 'sentence', 'My email is ana at gmail dot com.', 'Meu e-mail é ana arroba gmail ponto com.', '/maɪ ˈiːmeɪl ɪz ˈænə æt ˈdʒiːmeɪl dɑːt kɑːm/', '"@" = "at"; "." = "dot".', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"email","pos":"noun","ipa":"/ˈiːmeɪl/","gloss":"e-mail"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"ana","pos":"proper noun","ipa":"/ˈænə/","gloss":"Ana"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"gmail","pos":"proper noun","ipa":"/ˈdʒiːmeɪl/","gloss":"Gmail"},{"surface":"dot","pos":"noun","ipa":"/dɑːt/","gloss":"ponto (em endereço)"},{"surface":"com","pos":"noun","ipa":"/kɑːm/","gloss":"com (ponto com)"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-03-06', 'lesson-numbers-a1-03', 6, 'sentence', 'Is that with one l or two?', 'É com um l ou dois?', '/ɪz ðæt wɪð wʌn ɛl ɔːr tuː/', 'Para confirmar letras dobradas.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"l","pos":"noun","ipa":"/ɛl/","gloss":"letra L"},{"surface":"or","pos":"conjunction","ipa":"/ɔːr/","gloss":"ou"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-03-07', 'lesson-numbers-a1-03', 7, 'sentence', 'Let me read it back to you.', 'Deixa eu repetir para você.', '/lɛt miː riːd ɪt bæk tuː juː/', '"Read back" = ler de volta para confirmar.', '[]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"read","pos":"verb","ipa":"/riːd/","gloss":"ler"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-03-08', 'lesson-numbers-a1-03', 8, 'sentence', 'Sorry, I have the wrong number.', 'Desculpe, liguei para o número errado.', '/ˈsɑːri aɪ hæv ðə rɔːŋ ˈnʌmbər/', 'Frase para ligação errada.', '[]'::jsonb, '[{"surface":"Sorry","pos":"adjective","ipa":"/ˈsɑːri/","gloss":"desculpa"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"wrong","pos":"adjective","ipa":"/rɔːŋ/","gloss":"errado"},{"surface":"number","pos":"noun","ipa":"/ˈnʌmbər/","gloss":"número"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-03-09', 'lesson-numbers-a1-03', 9, 'sentence', 'Please call me back at this number.', 'Por favor, me retorne neste número.', '/pliːz kɔːl miː bæk æt ðɪs ˈnʌmbər/', '"At this number" = neste número.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"number","pos":"noun","ipa":"/ˈnʌmbər/","gloss":"número"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-03-10', 'lesson-numbers-a1-03', 10, 'sentence', 'Double five, three, seven.', 'Cinco cinco, três, sete.', '/ˈdʌbəl faɪv θriː ˈsɛvən/', 'Números repetidos: "double five" = 55.', '[]'::jsonb, '[{"surface":"Double","pos":"adjective","ipa":"/ˈdʌbəl/","gloss":"duplo (double five = 55)"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-numbers-a1-04-01', 'lesson-numbers-a1-04', 1, 'sentence', 'What time is it?', 'Que horas são?', '/wʌt taɪm ɪz ɪt/', 'Pergunta padrão. Também: "Do you have the time?".', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-04-02', 'lesson-numbers-a1-04', 2, 'sentence', 'It''s three o''clock.', 'São três em ponto.', '/ɪts θriː əˈklɑːk/', '"O''clock" só em hora cheia.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"},{"surface":"o''clock","pos":"adverb","ipa":"/əˈklɑːk/","gloss":"em ponto"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-04-03', 'lesson-numbers-a1-04', 3, 'sentence', 'It''s half past seven.', 'São sete e meia.', '/ɪts hæf pæst ˈsɛvən/', '"Half past" = e meia.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"half","pos":"noun","ipa":"/hæf/","gloss":"metade, meio"},{"surface":"past","pos":"preposition","ipa":"/pæst/","gloss":"depois de (horas)"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-04-04', 'lesson-numbers-a1-04', 4, 'sentence', 'It''s a quarter to nine.', 'São quinze para as nove.', '/ɪts ə ˈkwɔːrtər tuː naɪn/', '"Quarter to" = quinze para.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"quarter","pos":"noun","ipa":"/ˈkwɔːrtər/","gloss":"quarto (15 minutos)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"nine","pos":"numeral","ipa":"/naɪn/","gloss":"nove"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-04-05', 'lesson-numbers-a1-04', 5, 'sentence', 'It''s ten past four.', 'São quatro e dez.', '/ɪts tɛn pæst fɔːr/', '"Past" = depois da hora.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"},{"surface":"past","pos":"preposition","ipa":"/pæst/","gloss":"depois de (horas)"},{"surface":"four","pos":"numeral","ipa":"/fɔːr/","gloss":"quatro"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-04-06', 'lesson-numbers-a1-04', 6, 'sentence', 'It''s six forty-five.', 'São seis e quarenta e cinco.', '/ɪts sɪks ˌfɔːrtiˈfaɪv/', 'Forma digital: hora + minutos.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"six","pos":"numeral","ipa":"/sɪks/","gloss":"seis"},{"surface":"forty-five","pos":"numeral","ipa":"/ˌfɔːrtiˈfaɪv/","gloss":"quarenta e cinco"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-04-07', 'lesson-numbers-a1-04', 7, 'sentence', 'The meeting is at nine in the morning.', 'A reunião é às nove da manhã.', '/ðə ˈmiːtɪŋ ɪz æt naɪn ɪn ðə ˈmɔːrnɪŋ/', '"In the morning" = da manhã.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"nine","pos":"numeral","ipa":"/naɪn/","gloss":"nove"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-04-08', 'lesson-numbers-a1-04', 8, 'sentence', 'The store closes at eight at night.', 'A loja fecha às oito da noite.', '/ðə stɔːr ˈkloʊzɪz æt eɪt æt naɪt/', '"At night" = da noite.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"closes","pos":"verb","ipa":"/ˈkloʊzɪz/","gloss":"fecha"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-04-09', 'lesson-numbers-a1-04', 9, 'sentence', 'I get up at six thirty.', 'Acordo às seis e meia.', '/aɪ ɡɛt ʌp æt sɪks ˈθɜːrti/', '"Six thirty" = 6h30.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"six","pos":"numeral","ipa":"/sɪks/","gloss":"seis"},{"surface":"thirty","pos":"numeral","ipa":"/ˈθɜːrti/","gloss":"trinta"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-04-10', 'lesson-numbers-a1-04', 10, 'sentence', 'It''s almost midnight.', 'É quase meia-noite.', '/ɪts ˈɔːlmoʊst ˈmɪdnaɪt/', '"Almost" = quase.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"almost","pos":"adverb","ipa":"/ˈɔːlmoʊst/","gloss":"quase"},{"surface":"midnight","pos":"noun","ipa":"/ˈmɪdnaɪt/","gloss":"meia-noite"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-numbers-a1-05-01', 'lesson-numbers-a1-05', 1, 'sentence', 'What''s the date today?', 'Que dia é hoje?', '/wʌts ðə deɪt təˈdeɪ/', 'Pergunta pela data.', '[]'::jsonb, '[{"surface":"What''s","pos":"pronoun","ipa":"/wʌts/","gloss":"qual é"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"date","pos":"noun","ipa":"/deɪt/","gloss":"data"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-05-02', 'lesson-numbers-a1-05', 2, 'sentence', 'Today is May first.', 'Hoje é primeiro de maio.', '/təˈdeɪ ɪz meɪ fɜːrst/', 'Datas usam ordinais: first, second, third.', '[]'::jsonb, '[{"surface":"Today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"May","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-05-03', 'lesson-numbers-a1-05', 3, 'sentence', 'My birthday is on June third.', 'Meu aniversário é três de junho.', '/maɪ ˈbɜːrθdeɪ ɪz ɑːn dʒuːn θɜːrd/', '"On" + data.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"birthday","pos":"noun","ipa":"/ˈbɜːrθdeɪ/","gloss":"aniversário"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"June","pos":"proper noun","ipa":"/dʒuːn/","gloss":"junho"},{"surface":"third","pos":"adjective","ipa":"/θɜːrd/","gloss":"terceiro"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-05-04', 'lesson-numbers-a1-05', 4, 'sentence', 'I was born in nineteen ninety.', 'Nasci em mil novecentos e noventa.', '/aɪ wɑːz bɔːrn ɪn ˌnaɪnˈtiːn ˈnaɪnti/', 'Anos lidos em pares: "nineteen ninety".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"born","pos":"verb","ipa":"/bɔːrn/","gloss":"nascido (be born = nascer)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"nineteen","pos":"numeral","ipa":"/ˌnaɪnˈtiːn/","gloss":"dezenove"},{"surface":"ninety","pos":"numeral","ipa":"/ˈnaɪnti/","gloss":"noventa"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-05-05', 'lesson-numbers-a1-05', 5, 'sentence', 'She was born in two thousand ten.', 'Ela nasceu em dois mil e dez.', '/ʃiː wɑːz bɔːrn ɪn tuː ˈθaʊzənd tɛn/', 'Anos 2000: "two thousand ten" ou "twenty ten".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"born","pos":"verb","ipa":"/bɔːrn/","gloss":"nascido (be born = nascer)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"thousand","pos":"numeral","ipa":"/ˈθaʊzənd/","gloss":"mil"},{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-05-06', 'lesson-numbers-a1-05', 6, 'sentence', 'Happy birthday!', 'Feliz aniversário!', '/ˈhæpi ˈbɜːrθdeɪ/', 'Cumprimento padrão.', '[]'::jsonb, '[{"surface":"Happy","pos":"adjective","ipa":"/ˈhæpi/","gloss":"feliz"},{"surface":"birthday","pos":"noun","ipa":"/ˈbɜːrθdeɪ/","gloss":"aniversário"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-05-07', 'lesson-numbers-a1-05', 7, 'sentence', 'When is your birthday?', 'Quando é seu aniversário?', '/wɛn ɪz jʊr ˈbɜːrθdeɪ/', 'Pergunta com "when".', '[]'::jsonb, '[{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"birthday","pos":"noun","ipa":"/ˈbɜːrθdeɪ/","gloss":"aniversário"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-05-08', 'lesson-numbers-a1-05', 8, 'sentence', 'The party is on Saturday the fifth.', 'A festa é no sábado, dia cinco.', '/ðə ˈpɑːrti ɪz ɑːn ˈsætərdeɪ ðə fɪfθ/', 'Dia da semana + "the" + ordinal.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"party","pos":"noun","ipa":"/ˈpɑːrti/","gloss":"festa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Saturday","pos":"proper noun","ipa":"/ˈsætərdeɪ/","gloss":"sábado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"fifth","pos":"adjective","ipa":"/fɪfθ/","gloss":"quinto"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-05-09', 'lesson-numbers-a1-05', 9, 'sentence', 'We got married in two thousand fifteen.', 'Nos casamos em dois mil e quinze.', '/wiː ɡɑːt ˈmærid ɪn tuː ˈθaʊzənd ˌfɪfˈtiːn/', '"Get married" = casar-se.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"married","pos":"adjective","ipa":"/ˈmærid/","gloss":"casado"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"thousand","pos":"numeral","ipa":"/ˈθaʊzənd/","gloss":"mil"},{"surface":"fifteen","pos":"numeral","ipa":"/ˌfɪfˈtiːn/","gloss":"quinze"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-05-10', 'lesson-numbers-a1-05', 10, 'sentence', 'Christmas is on December twenty-fifth.', 'O Natal é no dia vinte e cinco de dezembro.', '/ˈkrɪsməs ɪz ɑːn dɪˈsɛmbər ˌtwɛntiˈfɪfθ/', 'Ordinais compostos: twenty-fifth.', '[]'::jsonb, '[{"surface":"Christmas","pos":"proper noun","ipa":"/ˈkrɪsməs/","gloss":"Natal"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"December","pos":"proper noun","ipa":"/dɪˈsɛmbər/","gloss":"dezembro"},{"surface":"twenty-fifth","pos":"adjective","ipa":"/ˌtwɛntiˈfɪfθ/","gloss":"vigésimo quinto"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-numbers-a1-06-01', 'lesson-numbers-a1-06', 1, 'sentence', 'Are you free on Tuesday?', 'Você está livre na terça?', '/ɑːr juː friː ɑːn ˈtuːzdeɪ/', '"Free" = disponível.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Tuesday","pos":"proper noun","ipa":"/ˈtuːzdeɪ/","gloss":"terça-feira"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-06-02', 'lesson-numbers-a1-06', 2, 'sentence', 'How about Thursday at three?', 'Que tal quinta às três?', '/haʊ əˈbaʊt ˈθɜːrzdeɪ æt θriː/', '"How about" = que tal.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"Thursday","pos":"proper noun","ipa":"/ˈθɜːrzdeɪ/","gloss":"quinta-feira"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-06-03', 'lesson-numbers-a1-06', 3, 'sentence', 'That works for me.', 'Para mim está ótimo.', '/ðæt wɜːrks fɔːr miː/', 'Confirma o horário.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"works","pos":"verb","ipa":"/wɜːrks/","gloss":"funciona, serve"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-06-04', 'lesson-numbers-a1-06', 4, 'sentence', 'I''m busy until noon.', 'Estou ocupado até o meio-dia.', '/aɪm ˈbɪzi ənˈtɪl nuːn/', '"Until" = até.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"busy","pos":"adjective","ipa":"/ˈbɪzi/","gloss":"ocupado"},{"surface":"until","pos":"conjunction","ipa":"/ənˈtɪl/","gloss":"até"},{"surface":"noon","pos":"noun","ipa":"/nuːn/","gloss":"meio-dia"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-06-05', 'lesson-numbers-a1-06', 5, 'sentence', 'Can we move it to next week?', 'Podemos passar para semana que vem?', '/kæn wiː muːv ɪt tuː nɛkst wiːk/', '"Move" = remarcar.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"move","pos":"verb","ipa":"/muːv/","gloss":"mover, passar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-06-06', 'lesson-numbers-a1-06', 6, 'sentence', 'Let''s meet in two hours.', 'Vamos nos encontrar daqui a duas horas.', '/lɛts miːt ɪn tuː aʊərz/', '"In" + período = daqui a.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"meet","pos":"verb","ipa":"/miːt/","gloss":"encontrar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"hours","pos":"noun","ipa":"/aʊərz/","gloss":"horas"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-06-07', 'lesson-numbers-a1-06', 7, 'sentence', 'The appointment is at ten fifteen.', 'A consulta é às dez e quinze.', '/ðə əˈpɔɪntmənt ɪz æt tɛn ˌfɪfˈtiːn/', '"Ten fifteen" = 10h15.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"appointment","pos":"noun","ipa":"/əˈpɔɪntmənt/","gloss":"consulta, horário marcado"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"},{"surface":"fifteen","pos":"numeral","ipa":"/ˌfɪfˈtiːn/","gloss":"quinze"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-06-08', 'lesson-numbers-a1-06', 8, 'sentence', 'I''ll be there in five minutes.', 'Chego em cinco minutos.', '/aɪl biː ðɛr ɪn faɪv ˈmɪnɪts/', '"Be there" = chegar lá.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"minutes","pos":"noun","ipa":"/ˈmɪnɪts/","gloss":"minutos"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-06-09', 'lesson-numbers-a1-06', 9, 'sentence', 'See you on the twentieth.', 'Te vejo no dia vinte.', '/siː juː ɑːn ðə ˈtwɛntiəθ/', 'Só o dia: "the twentieth".', '[]'::jsonb, '[{"surface":"See","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"twentieth","pos":"adjective","ipa":"/ˈtwɛntiəθ/","gloss":"vigésimo"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-06-10', 'lesson-numbers-a1-06', 10, 'sentence', 'The deadline is the end of the month.', 'O prazo é o fim do mês.', '/ðə ˈdɛdlaɪn ɪz ðə ɛnd ʌv ðə mʌnθ/', '"The end of" = o fim de.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"deadline","pos":"noun","ipa":"/ˈdɛdlaɪn/","gloss":"prazo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"end","pos":"noun","ipa":"/ɛnd/","gloss":"fim, final"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-numbers-a1-07-01', 'lesson-numbers-a1-07', 1, 'sentence', 'I am one meter seventy tall.', 'Tenho um metro e setenta de altura.', '/aɪ æm wʌn ˈmiːtər ˈsɛvənti tɔːl/', 'Nos EUA usam pés: "five foot seven".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"meter","pos":"noun","ipa":"/ˈmiːtər/","gloss":"metro"},{"surface":"seventy","pos":"numeral","ipa":"/ˈsɛvənti/","gloss":"setenta"},{"surface":"tall","pos":"adjective","ipa":"/tɔːl/","gloss":"alto"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-07-02', 'lesson-numbers-a1-07', 2, 'sentence', 'It weighs two kilos.', 'Pesa dois quilos.', '/ɪt weɪz tuː ˈkiːloʊz/', '"Weigh" = pesar. Nos EUA: libras ("pounds").', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"weighs","pos":"verb","ipa":"/weɪz/","gloss":"pesa"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"kilos","pos":"noun","ipa":"/ˈkiːloʊz/","gloss":"quilos"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-07-03', 'lesson-numbers-a1-07', 3, 'sentence', 'The beach is ten kilometers away.', 'A praia fica a dez quilômetros.', '/ðə biːtʃ ɪz tɛn kɪˈlɑːmɪtərz əˈweɪ/', '"Away" indica distância.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"beach","pos":"noun","ipa":"/biːtʃ/","gloss":"praia"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"},{"surface":"kilometers","pos":"noun","ipa":"/kɪˈlɑːmɪtərz/","gloss":"quilômetros"},{"surface":"away","pos":"adverb","ipa":"/əˈweɪ/","gloss":"embora; (right away) já"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-07-04', 'lesson-numbers-a1-07', 4, 'sentence', 'It is five miles from here.', 'Fica a cinco milhas daqui.', '/ɪt ɪz faɪv maɪlz frʌm hɪr/', 'Uma milha ≈ 1,6 km.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"miles","pos":"noun","ipa":"/maɪlz/","gloss":"milhas"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-07-05', 'lesson-numbers-a1-07', 5, 'sentence', 'It''s thirty degrees today.', 'Está trinta graus hoje.', '/ɪts ˈθɜːrti dɪˈɡriːz təˈdeɪ/', 'Nos EUA a temperatura é em Fahrenheit: 86°F ≈ 30°C.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"thirty","pos":"numeral","ipa":"/ˈθɜːrti/","gloss":"trinta"},{"surface":"degrees","pos":"noun","ipa":"/dɪˈɡriːz/","gloss":"graus"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-07-06', 'lesson-numbers-a1-07', 6, 'sentence', 'A liter of milk, please.', 'Um litro de leite, por favor.', '/ə ˈliːtər ʌv mɪlk pliːz/', 'Nos EUA também se usa "gallon" (≈ 3,8 litros).', '[]'::jsonb, '[{"surface":"A","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"liter","pos":"noun","ipa":"/ˈliːtər/","gloss":"litro"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"milk","pos":"noun","ipa":"/mɪlk/","gloss":"leite"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-07-07', 'lesson-numbers-a1-07', 7, 'sentence', 'The room is twenty square meters.', 'O quarto tem vinte metros quadrados.', '/ðə ruːm ɪz ˈtwɛnti skwɛr ˈmiːtərz/', '"Square meters" = metros quadrados.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"twenty","pos":"numeral","ipa":"/ˈtwɛnti/","gloss":"vinte"},{"surface":"square","pos":"noun","ipa":"/skwɛr/","gloss":"praça"},{"surface":"meters","pos":"noun","ipa":"/ˈmiːtərz/","gloss":"metros"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-07-08', 'lesson-numbers-a1-07', 8, 'sentence', 'Cook it for twenty minutes.', 'Cozinhe por vinte minutos.', '/kʊk ɪt fɔːr ˈtwɛnti ˈmɪnɪts/', '"For" + tempo.', '[]'::jsonb, '[{"surface":"Cook","pos":"noun","ipa":"/kʊk/","gloss":"cozinheiro"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"twenty","pos":"numeral","ipa":"/ˈtwɛnti/","gloss":"vinte"},{"surface":"minutes","pos":"noun","ipa":"/ˈmɪnɪts/","gloss":"minutos"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-07-09', 'lesson-numbers-a1-07', 9, 'sentence', 'Add half a cup of sugar.', 'Adicione meia xícara de açúcar.', '/æd hæf ə kʌp ʌv ˈʃʊɡər/', '"Half a cup" = meia xícara.', '[]'::jsonb, '[{"surface":"Add","pos":"verb","ipa":"/æd/","gloss":"acrescentar"},{"surface":"half","pos":"noun","ipa":"/hæf/","gloss":"metade, meio"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"cup","pos":"noun","ipa":"/kʌp/","gloss":"xícara"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"sugar","pos":"noun","ipa":"/ˈʃʊɡər/","gloss":"açúcar"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-07-10', 'lesson-numbers-a1-07', 10, 'sentence', 'How far is it?', 'Qual é a distância?', '/haʊ fɑːr ɪz ɪt/', '"How far" pergunta distância.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"far","pos":"adjective","ipa":"/fɑːr/","gloss":"longe"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-numbers-a1-08-01', 'lesson-numbers-a1-08', 1, 'sentence', 'I am thirty years old.', 'Tenho trinta anos.', '/aɪ æm ˈθɜːrti jɪrz oʊld/', 'Revisão de idade.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"thirty","pos":"numeral","ipa":"/ˈθɜːrti/","gloss":"trinta"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-08-02', 'lesson-numbers-a1-08', 2, 'sentence', 'It''s nineteen ninety-nine.', 'Custa dezenove e noventa e nove.', '/ɪts ˌnaɪnˈtiːn ˌnaɪntiˈnaɪn/', 'Revisão de preço em dois blocos.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"nineteen","pos":"numeral","ipa":"/ˌnaɪnˈtiːn/","gloss":"dezenove"},{"surface":"ninety-nine","pos":"numeral","ipa":"/ˌnaɪntiˈnaɪn/","gloss":"noventa e nove"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-08-03', 'lesson-numbers-a1-08', 3, 'sentence', 'Can you spell that, please?', 'Pode soletrar, por favor?', '/kæn juː spɛl ðæt pliːz/', 'Revisão de soletrar.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"spell","pos":"verb","ipa":"/spɛl/","gloss":"soletrar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-08-04', 'lesson-numbers-a1-08', 4, 'sentence', 'It''s a quarter past two.', 'São duas e quinze.', '/ɪts ə ˈkwɔːrtər pæst tuː/', 'Revisão de horas: "quarter past".', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"quarter","pos":"noun","ipa":"/ˈkwɔːrtər/","gloss":"quarto (15 minutos)"},{"surface":"past","pos":"preposition","ipa":"/pæst/","gloss":"depois de (horas)"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-08-05', 'lesson-numbers-a1-08', 5, 'sentence', 'My birthday is on April tenth.', 'Meu aniversário é dez de abril.', '/maɪ ˈbɜːrθdeɪ ɪz ɑːn ˈeɪprəl tɛnθ/', 'Revisão de datas com ordinal.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"birthday","pos":"noun","ipa":"/ˈbɜːrθdeɪ/","gloss":"aniversário"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"April","pos":"proper noun","ipa":"/ˈeɪprəl/","gloss":"abril"},{"surface":"tenth","pos":"adjective","ipa":"/tɛnθ/","gloss":"décimo"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-08-06', 'lesson-numbers-a1-08', 6, 'sentence', 'How about Friday at noon?', 'Que tal sexta ao meio-dia?', '/haʊ əˈbaʊt ˈfraɪdeɪ æt nuːn/', 'Revisão de agenda.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"Friday","pos":"proper noun","ipa":"/ˈfraɪdeɪ/","gloss":"sexta-feira"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"noon","pos":"noun","ipa":"/nuːn/","gloss":"meio-dia"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-08-07', 'lesson-numbers-a1-08', 7, 'sentence', 'It is two hours from here.', 'Fica a duas horas daqui.', '/ɪt ɪz tuː aʊərz frʌm hɪr/', 'Revisão de distância em tempo.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"hours","pos":"noun","ipa":"/aʊərz/","gloss":"horas"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-08-08', 'lesson-numbers-a1-08', 8, 'sentence', 'My number is double seven, one, oh.', 'Meu número é sete sete, um, zero.', '/maɪ ˈnʌmbər ɪz ˈdʌbəl ˈsɛvən wʌn oʊ/', 'Revisão: "double" e "oh".', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"number","pos":"noun","ipa":"/ˈnʌmbər/","gloss":"número"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"double","pos":"adjective","ipa":"/ˈdʌbəl/","gloss":"duplo (double five = 55)"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"oh","pos":"interjection","ipa":"/oʊ/","gloss":"ah, oh"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-08-09', 'lesson-numbers-a1-08', 9, 'sentence', 'We were born in the same year.', 'Nascemos no mesmo ano.', '/wiː wɜːr bɔːrn ɪn ðə seɪm jɪr/', 'Revisão de "be born".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"born","pos":"verb","ipa":"/bɔːrn/","gloss":"nascido (be born = nascer)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"same","pos":"adjective","ipa":"/seɪm/","gloss":"mesmo"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"}]'::jsonb, NULL, NULL),
  ('unit-numbers-a1-08-10', 'lesson-numbers-a1-08', 10, 'sentence', 'See you at eight sharp.', 'Te vejo às oito em ponto.', '/siː juː æt eɪt ʃɑːrp/', '"Sharp" = em ponto (pontual).', '[]'::jsonb, '[{"surface":"See","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"},{"surface":"sharp","pos":"adverb","ipa":"/ʃɑːrp/","gloss":"em ponto"}]'::jsonb, NULL, NULL)
